<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Api\Concerns\HandlesDomainModules; use App\Http\Controllers\Controller; use App\Http\Requests\MarketingModuleRequest; use Illuminate\Http\JsonResponse; class MarketingModuleController extends Controller { use HandlesDomainModules; protected function domain(): string { return 'marketing'; } public function store(MarketingModuleRequest $request, string $module): JsonResponse { $this->registry->assertDomain($this->domain(), $module); return response()->json($this->service->create($request, $module, $request->validated()), 201); } public function update(MarketingModuleRequest $request, string $module, int $id): JsonResponse { $this->registry->assertDomain($this->domain(), $module); return response()->json($this->service->update($request, $module, $id, $request->validated())); } }
